using System;using System.IO;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using Mewgic.Map;
[InitializeOnLoad]public static class MapWorldTests
{
 static readonly List<string> checks=new List<string>();static int step;static double next;static float clock;
 static MapWorld W=>UnityEngine.Object.FindFirstObjectByType<MapWorld>();
 static MapWorldTests(){EditorApplication.update+=Tick;}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");checks.Clear();step=0;SessionState.SetBool("MapWorldTest",true);EditorSceneManager.OpenScene("Assets/Scenes/LevelMap.unity");EditorApplication.isPlaying=true;next=EditorApplication.timeSinceStartup+2;}
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks.Add(name);}
 static void Click(string name){Canvas.ForceUpdateCanvases();var g=GameObject.Find(name);Check(g!=null,"Button exists: "+name);var r=(RectTransform)g.transform;var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);Check(hits.Count>0&&hits[0].gameObject==g,"Top raycast target: "+name);ExecuteEvents.Execute(g,d,ExecuteEvents.pointerClickHandler);}
 static Rect Bounds(RectTransform t,RectTransform relative){var c=new Vector3[4];t.GetWorldCorners(c);Vector2 min=Vector2.one*float.MaxValue,max=-min;foreach(var p in c){var v=(Vector2)relative.InverseTransformPoint(p);min=Vector2.Min(min,v);max=Vector2.Max(max,v);}return Rect.MinMaxRect(min.x,min.y,max.x,max.y);}
 public static void Capture(int width,int height,bool inset=false)
 {
  var w=W;var canvas=w.Canvas;var cam=Camera.main;var mode=canvas.renderMode;var camera=canvas.worldCamera;var plane=canvas.planeDistance;var min=w.SafeArea.anchorMin;var max=w.SafeArea.anchorMax;var target=cam.targetTexture;var old=RenderTexture.active;var rt=new RenderTexture(width,height,24);Texture2D tex=null;
  try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;cam.targetTexture=rt;if(inset){w.SafeArea.anchorMin=new Vector2(.04f,.05f);w.SafeArea.anchorMax=new Vector2(.96f,.96f);}Canvas.ForceUpdateCanvases();w.Layout();Canvas.ForceUpdateCanvases();
   Check(Mathf.Abs(w.WorldRoot.localScale.x-w.WorldRoot.localScale.y)<.001f,"Uniform world scale "+width+"x"+height+inset);Check(w.Content.rect.height>w.Viewport.rect.height,"Scrollable world "+height);
   foreach(var name in new[]{"MapHeader","RegionNavigation","MapNavigation"}){var b=Bounds((RectTransform)GameObject.Find(name).transform,w.SafeArea);Check(w.SafeArea.rect.Contains(b.min)&&w.SafeArea.rect.Contains(b.max),"Fixed UI inside safe area "+name+height+inset);Check(!b.Overlaps(Bounds(w.Viewport,w.SafeArea)),"Fixed UI avoids viewport "+name+height);}
   foreach(var p in w.Points){var r=(RectTransform)p.transform;var b=Bounds(r,w.WorldRoot);Check(w.WorldRoot.rect.Contains(b.min)&&w.WorldRoot.rect.Contains(b.max),"Point inside world "+p.name+height);Check(r.rect.width*canvas.scaleFactor*w.WorldRoot.localScale.x>=43.9f,"44px hit target "+p.name+width);}
   foreach(var a in w.Points)foreach(var b in w.Points)if(a!=b&&a.regionIndex==b.regionIndex)Check(!Bounds((RectTransform)a.transform,w.WorldRoot).Overlaps(Bounds((RectTransform)b.transform,w.WorldRoot)),"Distinct hit regions "+a.name+"/"+b.name+width);
   w.FocusRegion(0,false);cam.Render();RenderTexture.active=rt;tex=new Texture2D(width,height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes("docs/PART06A_LAYOUT_"+width+"x"+height+(inset?"_SAFE":"")+".png",tex.EncodeToPNG());
  }finally{cam.targetTexture=target;RenderTexture.active=old;canvas.renderMode=mode;canvas.worldCamera=camera;canvas.planeDistance=plane;w.SafeArea.anchorMin=min;w.SafeArea.anchorMax=max;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);Canvas.ForceUpdateCanvases();w.Layout();}
 }
 static void Finish(string error){SessionState.SetBool("MapWorldTest",false);File.WriteAllText("docs/PART06A_TEST_RESULTS.json",JsonUtility.ToJson(new Result{success=error==null,error=error,checks=checks.ToArray()},true));EditorApplication.isPlaying=false;}
 [Serializable]class Result{public bool success;public string error;public string[] checks;}
 static void Tick(){if(!SessionState.GetBool("MapWorldTest",false)||!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next)return;try{next=EditorApplication.timeSinceStartup+1.3;switch(step){
 case 0:Check(W!=null&&W.Mounted,"Actual LevelMap mounted");Check(W.Points.Count==16,"12 independent slots plus 4 chests");Check(!W.ProgressionConnected,"Progression deliberately disconnected");Check(UnityEngine.Object.FindFirstObjectByType<Mewgic.PrototypeApp>()==null,"No gameplay model created in map");Check(GameObject.Find("RegionTerrain").transform.childCount==4,"Four independent terrain layers");Check(W.Scroll.vertical&&!W.Scroll.horizontal&&W.Scroll.movementType==ScrollRect.MovementType.Clamped,"Vertical clamped scroll");Check(W.Viewport.GetComponent<RectMask2D>()!=null,"World clipped to viewport");clock=W.EnvironmentTime;break;
 case 1:Check(W.EnvironmentTime>clock,"Environment clock advances");Capture(900,1600);Capture(900,1950);Capture(900,2000);Capture(900,2000,true);Capture(360,640);Click("RegionJump_3");break;
 case 2:Check(W.ActiveRegion==3&&Mathf.Abs(W.Scroll.verticalNormalizedPosition-W.RegionScrollPosition(3))<.01f,"Sky Castle jump reaches target");Click("LevelSlot_3_1");break;
 case 3:Check(W.InformationVisible,"Slot shows honest preview information");Check(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="LevelMap","Slot does not launch unfinished level");Click("MapInfoClose");Click("Chest_3_0");break;
 case 4:Check(W.InformationVisible,"Chest shows unavailable notice");Click("MapInfoClose");Click("RegionJump_2");break;
 case 5:Check(W.ActiveRegion==2,"Moon Garden tab");Click("RegionJump_1");break;
 case 6:Check(W.ActiveRegion==1,"Crystal Falls tab");Click("RegionJump_0");break;
 case 7:Check(W.ActiveRegion==0,"Village tab");foreach(var p in W.Points){W.FocusRegion(p.regionIndex,false);Click(p.name);Check(W.InformationVisible,"Each point responds: "+p.name);Click("MapInfoClose");}var s=W.Scroll;W.FocusRegion(0,false);var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,W.Viewport.position)};s.OnInitializePotentialDrag(d);s.OnBeginDrag(d);d.position-=new Vector2(0,350);s.OnDrag(d);s.OnEndDrag(d);Check(s.verticalNormalizedPosition>.01f,"Real drag scrolls world");s.StopMovement();W.FocusRegion(1,false);float before=s.verticalNormalizedPosition;d.scrollDelta=new Vector2(0,3);s.OnScroll(d);Check(Mathf.Abs(before-s.verticalNormalizedPosition)>.001f,"Wheel scroll changes world offset");W.FocusRegion(0,false);ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART06A_GAMEVIEW.png");break;
 case 8:Click("MapHome");break;
 case 9:Check(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="Home","Map returns to Home");Finish(null);return;
 }step++;}catch(Exception e){Finish(e.ToString());}}
}
